const lgref=()=>{if(LGREF)return LGREF;const av=(a,f)=>a.reduce((s,x)=>s+f(x),0)/a.length,pv=p=>(p.pwr+p.ctl+p.brk)/3,b=[...BP].sort((x,y)=>y.ov-x.ov).slice(0,108),sp=PP.filter(p=>!p.rp).sort((x,y)=>y.ov-x.ov).slice(0,72),rp=PP.filter(p=>p.rp).sort((x,y)=>y.ov-x.ov).slice(0,72);return LGREF=[av(b,x=>x.con),av(b,x=>x.pow),av(b,x=>x.eye),av(b,x=>x.spd),av(b,x=>x.def),av(sp,pv),av(rp,pv)]};
const teamv=()=>{const lu=S.lu?S.lu.map(x=>x.b):(S.B||[]),av=(a,f)=>a.length?a.reduce((s,x)=>s+f(x),0)/a.length:0,pv=p=>(p.pwr+p.ctl+p.brk)/3,P=S.P||[],rl=S.rl||{},sp=P.filter(p=>rl[p.id]=='SP'),rp=P.filter(p=>['SU','RP','CL'].includes(rl[p.id])),spx=sp.length?sp:P.filter(p=>!p.rp),rpx=rp.length?rp:P.filter(p=>p.rp),df=S.lu?S.lu.reduce((s,x)=>s+(x.pos=='DH'?x.b.def:dv(x.b)*fm(x.b,x.pos)),0)/S.lu.length:av(lu,x=>x.def);return[av(lu,x=>x.con),av(lu,x=>x.pow),av(lu,x=>x.eye),av(lu,x=>x.spd),df,av(spx,pv),av(rpx,pv)]};
const RADL=['ミート','長打','選球','走力','守備','先発','救援'];
const radar=(a,b)=>{const n=a.length,cx=130,cy=125,R0=88,lo=30,hi=90,pt=(v,i,k)=>{const r=R0*Math.max(0,Math.min(1,(v-lo)/(hi-lo)))*(k||1),t=-Math.PI/2+2*Math.PI*i/n;return[(cx+r*Math.cos(t)).toFixed(1),(cy+r*Math.sin(t)).toFixed(1)]},poly=(arr,st)=>`<polygon points="${arr.map((v,i)=>pt(v,i).join(',')).join(' ')}" style="${st}"/>`,grid=[.33,.66,1].map(k=>`<polygon points="${RADL.map((_,i)=>pt(hi,i,k).join(',')).join(' ')}" style="fill:none;stroke:var(--ln)"/>`).join(''),lab=RADL.map((l,i)=>{const[x,y]=pt(hi,i,1.2);return`<text x=${x} y=${y} text-anchor=middle font-size=11 style="fill:var(--sb)">${l}</text>`}).join('');return`<svg viewBox="0 0 260 250" class=fl>${grid}${poly(b,'fill:rgba(120,120,120,.18);stroke:var(--sb);stroke-dasharray:4 3')}${poly(a,'fill:rgba(11,95,255,.25);stroke:var(--ac);stroke-width:2')}${lab}</svg>`};
const FP={C:[150,236],'1B':[232,158],'2B':[192,108],'3B':[68,158],SS:[108,108],LF:[52,56],CF:[150,32],RF:[248,56],DH:[262,236]};
const fld=()=>`<svg viewBox="0 0 300 268" class=fl><path d="M150 252 L272 140 L150 28 L28 140 Z" style="fill:rgba(21,128,61,.12);stroke:var(--ln)"/>${S.lu.map(x=>{const[px,py]=FP[x.pos]||[150,150],f=fm(x.b,x.pos),col=x.pos=='DH'?'var(--sb)':f>.95?'var(--ok)':f>.8?'#d97706':'var(--ng)',nm=x.b.n.length>4?x.b.n.slice(0,4):x.b.n;return`<g><circle cx=${px} cy=${py} r=21 style="fill:var(--cd);stroke:${col};stroke-width:2"/><text x=${px} y=${py-1} text-anchor=middle font-size=9 style="fill:var(--tx)">${nm}</text><text x=${px} y=${py+10} text-anchor=middle font-size=9 style="fill:var(--sb)">${x.pos} ${x.b.ov}</text></g>`}).join('')}</svg>`;
function vTeam(){const a=teamv(),b=lgref(),rl=S.rl||{},rows=[...(S.lu||(S.B||[]).map(p=>({b:p,pos:p.pos}))).map(x=>[x.b,x.pos=='DH'?'DH':x.pos]),...(S.bn||[]).map(p=>[p,BL[p.br]||'控え']),...(S.P||[]).map(p=>[p,RN[rl[p.id]]||(p.rp?'中継ぎ':'先発')]),...(S.bp||[]).map(p=>[p,BL[p.br]||'控え'])].sort((x,y)=>y[0].ov-x[0].ov);return`<h2>👥 ${S.name||'チーム'}</h2>${S.lu?`<h3>守備位置</h3><div class=c>${fld()}<div class=s>枠の色: 緑=◎本職 橙=○副業 赤=△不慣れ(DHは灰色)</div></div>`:''}<h3>戦力バランス</h3><div class=c>${radar(a,b)}<div class=s>青=自チーム 灰=各球団の主力平均(参考)</div><table>${RADL.map((l,i)=>`<tr><td>${l}</td><td>${a[i]?a[i].toFixed(1):'-'}</td><td class=s>${b[i].toFixed(1)}</td><td${a[i]?` style="color:var(--${a[i]>=b[i]?'ok':'ng'})"`:''}>${a[i]?(a[i]>=b[i]?'+':'')+(a[i]-b[i]).toFixed(1):''}</td></tr>`).join('')}</table></div><h3>選手一覧(OVR順)</h3><div class="c sc"><table><tr><th>選手</th><th>区分</th><th>OVR</th><th>特殊能力</th></tr>${rows.map(([p,k])=>`<tr><td>${p.n}${nw(p)}</td><td>${k}</td><td><b>${p.ov}</b></td><td>${(p.sk||[]).map(x=>SK[x][0]).join('・')||'-'}</td></tr>`).join('')}</table></div><div class=bb><button onclick="back2()">戻る</button></div>`}
/* 選手図鑑 */
function dxs(k,v){S.dx[k]=v;if(k!='n')S.dx.n=40;draw()}
function dxc(id){const c=S.dx.c,i=c.indexOf(id);if(i>=0)c.splice(i,1);else{if(c.length>=2)c.shift();c.push(id)}draw()}
const cmpv=(A,B)=>{const K=A.typ?[['球威','pwr'],['制球','ctl'],['変化球','brk'],['スタミナ','sta'],['総合','ov']]:[['ミート','con'],['長打','pow'],['選球','eye'],['走力','spd'],['守備','def'],['総合','ov']];return`<div class=c><div class=cmpt><b style="text-align:right">${A.n}</b><span></span><b>${B.n}</b>${K.map(([l,k])=>`<div style="display:flex;justify-content:flex-end;align-items:center;gap:4px"><span>${A[k]}</span><div class=bar style="width:${A[k]*.5}%;background:${A[k]>B[k]?'var(--ok)':'var(--sb)'}"></div></div><span class=s style="text-align:center">${l}</span><div style="display:flex;align-items:center;gap:4px"><div class=bar style="width:${B[k]*.5}%;background:${B[k]>A[k]?'var(--ok)':'var(--sb)'}"></div><span>${B[k]}</span></div>`).join('')}</div><div class=s style="display:flex;justify-content:space-between;margin-top:4px"><span>${TSYM[A.t]||A.t} ${A.age||''}歳 ${(A.sk||[]).map(x=>SK[x][0]).join('・')}</span><span>${TSYM[B.t]||B.t} ${B.age||''}歳 ${(B.sk||[]).map(x=>SK[x][0]).join('・')}</span></div></div>`};
function vDex(){const d=S.dx=S.dx||{t:'b',q:'',tm:'',ps:'',sk:'',so:'ov',n:40,c:[]},b=d.t=='b',pool=b?BP:PP,opt=(a,cur)=>a.map(([v,l])=>`<option value="${v}"${v==cur?' selected':''}>${l}</option>`).join(''),sel=(k,a)=>`<select onchange="dxs('${k}',this.value)">${opt(a,d[k])}</select>`;
 let L=pool.filter(p=>(!d.q||p.n.includes(d.q))&&(!d.tm||p.t==d.tm)&&(!d.ps||(b?(p.pos==d.ps||al(p).includes(d.ps)):(d.ps=='SP'?!p.rp:!!p.rp)))&&(!d.sk||(p.sk||[]).includes(d.sk)));
 L=[...L].sort((x,y)=>d.so=='age'?(x.age||99)-(y.age||99):(y[d.so]||0)-(x[d.so]||0));
 const cmp=d.c.map(id=>BP.find(p=>p.id==id)||PP.find(p=>p.id==id)).filter(Boolean),SO=b?[['ov','総合OVR'],['con','ミート'],['pow','長打'],['eye','選球'],['spd','走力'],['def','守備'],['age','年齢(若い順)']]:[['ov','総合OVR'],['pwr','球威'],['ctl','制球'],['brk','変化球'],['sta','スタミナ'],['age','年齢(若い順)']];
 return`<h2>📖 選手図鑑</h2><div class=nv><button class="${b?'':'g'}" onclick="dxs('t','b');S.dx.ps='';S.dx.so='ov';draw()">野手 ${BP.length}人</button><button class="${b?'g':''}" onclick="dxs('t','p');S.dx.ps='';S.dx.so='ov';draw()">投手 ${PP.length}人</button></div><div class=c><input value="${d.q.replace(/"/g,'')}" placeholder="名前で検索" onchange="dxs('q',this.value)"><div class=r style="margin-top:6px;flex-wrap:wrap">${sel('tm',[['','全球団'],...Object.entries(TSYM)])}${sel('ps',[['','全ポジション'],...(b?POS.filter(x=>x!='DH').map(x=>[x,PN2[x]]):[['SP','先発'],['RP','中継ぎ']])])}${sel('sk',[['','特殊能力:すべて'],...Object.entries(SK).map(([k,v])=>[k,v[0]])])}${sel('so',SO)}</div><div class=s>${L.length}人が該当 ・ チェックを2人付けると比較できます</div></div>${cmp.length==2&&!cmp[0].typ==!cmp[1].typ?cmpv(cmp[0],cmp[1]):cmp.length==2?'<p class=s>野手と投手は比較できません</p>':''}${L.slice(0,d.n).map(p=>`<div class=c><div class=h><input type=checkbox style="width:auto" ${d.c.includes(p.id)?'checked':''} onchange="dxc('${p.id}')"><b>${p.n}</b><span class=s>${TSYM[p.t]||p.t} ${p.age||''}歳 / ${b?p.pos+(p.alt?'(副'+al(p).join('・')+')':''):(p.rp?'中継ぎ':'先発')}</span><em>${p.ov}</em></div>${skc(p)}<div class=s>${abl(p)}</div><div class=s>${p.x}</div></div>`).join('')}${L.length>d.n?`<button class=g style="width:100%" onclick="dxs('n',${d.n+40})">もっと見る</button>`:''}<div class=bb><button onclick="back2()">戻る</button></div>`}
/* 毎年の入れ替え(控え⇔スタメン) */
function bsPick(side,id){const bs=S.bs=S.bs||{a:null,b:null,log:[]};bs[side]=bs[side]==id?null:id;draw()}
function bsKind(){const bs=S.bs||{},a=bs.a,b=bs.b;if(!a||!b)return 0;if(S.lu.some(x=>x.b.id==a)&&S.bn.some(p=>p.id==b))return'b';if(S.P.some(p=>p.id==a)&&S.bp.some(p=>p.id==b))return'p';return 0}
function bsDo(){const k=bsKind(),bs=S.bs;if(!k)return;if(k=='b'){const li=S.lu.findIndex(x=>x.b.id==bs.a),bi=S.bn.findIndex(p=>p.id==bs.b),A=S.lu[li].b,B=S.bn[bi];A.br=B.br;delete B.br;S.lu[li].b=B;S.bn[bi]=A;bs.log.push(`${B.n} がスタメン(${S.lu[li].pos})へ / ${A.n} は控え(${BL[A.br]})へ`)}else{const pi=S.P.findIndex(p=>p.id==bs.a),qi=S.bp.findIndex(p=>p.id==bs.b),A=S.P[pi],B=S.bp[qi],r=S.rl[A.id];A.br=B.br;delete B.br;S.rl[B.id]=r;delete S.rl[A.id];S.P[pi]=B;S.bp[qi]=A;bs.log.push(`${B.n} が${RN[r]}へ / ${A.n} は控え(${BL[A.br]})へ`)}bs.a=null;bs.b=null;draw()}
function bsDone(){S.bs=null;go('lineup')}
function vBSW(){const bs=S.bs=S.bs||{a:null,b:null,log:[]},k=bsKind(),row=(p,side,tag)=>`<div class="c pc ${bs[side]==p.id?'on':''}" onclick="bsPick('${side}','${p.id}')"><div class=h><b>${p.n}</b>${nw(p)}<span class=s>${tag} / ${p.typ?(p.rp?'中継ぎ向き':'先発向き'):p.pos+(p.alt?'(副'+al(p).join('・')+')':'')}</span><em>${p.ov}</em></div>${skc(p)}<div class=s>${abl(p)}</div></div>`,A=[...S.lu.map(x=>x.b),...S.P].find(p=>p.id==bs.a),B=[...S.bn,...S.bp].find(p=>p.id==bs.b),pv=k=='b'?(()=>{const x=S.lu.find(z=>z.b.id==A.id);return`${x.pos}の適性 ${fl(B,x.pos)} / OVR ${A.ov}→${B.ov}`})():k=='p'?`OVR ${A.ov}→${B.ov}`:'';return`<h2>控えとスタメンの入れ替え</h2><p class=s>スタメン(上)と控え(下)を1人ずつ選んで「入れ替える」。何度でも交換できます。控えの枠(代打・守備・代走など)は、控えに回った選手が引き継ぎます。</p><h3>野手スタメン</h3>${S.lu.map(x=>row(x.b,'a',x.pos)).join('')}<h3>控え野手</h3>${S.bn.map(p=>row(p,'b',BL[p.br])).join('')}<h3>投手(先発・救援)</h3>${S.P.map(p=>row(p,'a',RN[S.rl[p.id]]||'')).join('')}<h3>控え投手</h3>${S.bp.map(p=>row(p,'b',BL[p.br])).join('')}${bs.log.length?`<div class=c><b>入れ替え済み</b>${bs.log.map(t=>`<div class=s>${t}</div>`).join('')}</div>`:''}<div class=bb><button class=g onclick="bsDo()" ${k?'':'disabled'}>入れ替える${pv?'<br><span style="font-size:10px">'+pv+'</span>':''}</button><button onclick="bsDone()">${bs.log.length?'確定して進む':'このまま進む'}</button></div>`}
/* シーズンの見どころ */
function hlights(r){if(!r.gl||r.gl.length<10)return'';const g=r.gl,n=g.length;let d=0,mx=0,mn=0;const tr=g.map(x=>{d+=x[0]>x[1]?1:x[0]<x[1]?-1:0;mx=Math.max(mx,d);mn=Math.min(mn,d);return d});
 const W=330,H=120,px=i=>8+i*(W-16)/(n-1),py=v=>10+(mx-v)*(H-20)/((mx-mn)||1),pts=tr.map((v,i)=>px(i).toFixed(1)+','+py(v).toFixed(1)).join(' '),il=g.map((x,i)=>x[3]?i:-1).filter(i=>i>=0);
 let cw=0,cl=0,bw=[0,0],bl=[0,0],swin=0,sloss=0,w1=0,l1=0,bigW=null,bigL=null;
 g.forEach((x,i)=>{const df=x[0]-x[1];if(df>0){cw++;cl=0;if(cw>bw[0])bw=[cw,i-cw+2];if(x[1]==0)swin++;if(df==1)w1++;if(!bigW||df>bigW.d)bigW={d:df,i,x}}else if(df<0){cl++;cw=0;if(cl>bl[0])bl=[cl,i-cl+2];if(x[0]==0)sloss++;if(df==-1)l1++;if(!bigL||-df>bigL.d)bigL={d:-df,i,x}}else{cw=0;cl=0}});
 return`<h3>シーズンの見どころ</h3><div class=c><div class=s>貯金の推移(最終 ${d>=0?'+':''}${d}${il.length?' / 灰色の帯は交流戦':''})</div><svg viewBox="0 0 ${W} ${H}" class=fl>${il.length?`<rect x=${px(il[0]).toFixed(1)} y=0 width=${(px(il[il.length-1])-px(il[0])).toFixed(1)} height=${H} style="fill:rgba(120,120,120,.15)"/>`:''}<line x1=8 x2=${W-8} y1=${py(0).toFixed(1)} y2=${py(0).toFixed(1)} style="stroke:var(--sb);stroke-dasharray:3 3"/><polyline points="${pts}" style="fill:none;stroke:var(--ac);stroke-width:2"/></svg><div class=s>最長連勝 <b>${bw[0]}</b>(${bw[1]}〜${bw[1]+bw[0]-1}試合目) ・ 最長連敗 <b>${bl[0]}</b>(${bl[1]}〜${bl[1]+bl[0]-1}試合目)<br>完封勝ち ${swin}回 ・ 完封負け ${sloss}回 ・ 1点差ゲーム ${w1}勝${l1}敗${bigW?`<br>最大点差勝利 ${bigW.d}点差(${bigW.i+1}試合目 ${bigW.x[2]}戦 ${bigW.x[0]}-${bigW.x[1]})`:''}${bigL?`<br>最大点差敗戦 ${bigL.d}点差(${bigL.i+1}試合目 ${bigL.x[2]}戦 ${bigL.x[0]}-${bigL.x[1]})`:''}</div></div>${r.mm&&r.mm.some(x=>x)?`<div class=c><b>月間MVP</b>${r.mm.map((m,i)=>m?`<div class=s>${MN2[i]}: <b>${m.n}</b> ${m.v}</div>`:'').join('')}</div>`:''}`}
/* ---------- 複数年・控え ---------- */
const ri=(a,b)=>a+Math.floor(R()*(b-a+1));
const saveG=()=>{try{localStorage.setItem('npbsave',JSON.stringify({name:S.name,lg:S.lg,year:S.year,lu:S.lu,P:S.P,rl:S.rl,bn:S.bn,bp:S.bp,hist:S.hist,res:S.res}));S.saveMsg='';return true}catch(e){S.saveMsg='保存に失敗しました。ブラウザの空き容量・プライベートブラウズ設定をご確認ください。';return false}};
const validSave=d=>!!d&&typeof d==='object'&&typeof d.name==='string'&&Array.isArray(d.lu)&&d.lu.length===9&&d.lu.every(x=>x&&x.b&&x.b.id!=null)&&Array.isArray(d.P)&&d.P.length===12&&d.P.every(x=>x&&x.id!=null)&&Array.isArray(d.bn||[])&&Array.isArray(d.bp||[])&&d.rl&&typeof d.rl==='object'&&Number.isFinite(Number(d.year))&&Number(d.year)>=2026&&(d.lg==='セ'||d.lg==='パ');
const loadG=()=>{try{const d=JSON.parse(localStorage.getItem('npbsave')||'null');return validSave(d)?d:null}catch(e){return null}};
const cs=()=>{const d=loadG();return d?`<div class=c><b>続きから</b><p class=s>${d.name}:${d.year}年終了時点</p><button onclick="cont()">続きから</button></div>`:''};
function cont(){const d=loadG();if(d){S={v:'cont',ph:'p',bn:[],bp:[],...d};S.name=safeName(S.name);S.bn=Array.isArray(S.bn)?S.bn:[];S.bp=Array.isArray(S.bp)?S.bp:[];[...(S.lu||[]).map(x=>x.b),...(S.P||[]),...S.bn,...S.bp].forEach(p=>{if(p.sk===undefined){const q=(p.typ?PP:BP).find(z=>z.id==p.id);p.sk=q&&q.sk?[...q.sk]:p.typ?skP(p):skB(p)}});draw()}}
function vCont(){return`<h2>${S.name} <span class=s>${S.lg||'セ'}・リーグ</span></h2><div class=c>${(S.hist||[]).map(h=>hl(h)).join('<br>')}</div><div class=bb><button class=g onclick="go('home')">ホーム</button><button onclick="nextYear()">次年度へ</button></div>`}
function redo(p){if(p.typ){p.rt=56+(prw(p)-56)*p.rel;p.ov=cl(rd(itp(p.rt,AP))-(p.rp?2:0),35,95)}else{p.bt=51+(.3*p.con+.3*p.pow+.15*p.eye+.1*p.spd+.15*p.def-51)*p.rel;p.ov=cl(rd(itp(p.bt,AB))+(PB[p.pos]||0),35,95)}}
/* 加齢: 36歳以上はランダムに低下、29歳以下はランダムに大幅アップあり */
function evolve(p){const K=p.typ?['pwr','ctl','brk','sta']:['con','pow','eye','spd','def'],a=p.age?++p.age:27;p.big=0;
 if(a>=36){K.forEach(k=>{if(R()<.65){const f=(k=='spd'||k=='pwr'||k=='sta')?2:1;p[k]=cl(p[k]-ri(1,3)*f-(a>=39?ri(0,2):0),30,99)}})}
 else{const up=a<=29;K.forEach(k=>{p[k]=cl(p[k]+ri(up?-1:-2,up?2:1),30,99)});
  const ch=p.bake&&a<=29?.6:a<=25?.3:a<=29?.18:0;if(ch&&R()<ch){const n=R()<.35?2:1;for(let i=0;i<n;i++){const k=K[ri(0,K.length-1)];p[k]=cl(p[k]+ri(6,14),30,99);p.big++}}}
 redo(p);skUpd(p)}
const f3=x=>x>=1?x.toFixed(3):x.toFixed(3).slice(1);
const xt=(p,s)=>{if(!p.typ){const ab=s.AB||0,h=s.H||0,pa=s.PA||0;return`${S.year}年 打率${ab?f3(h/ab):'.---'} ${s.HR||0}本 ${s.RBI||0}点 ${s.SB||0}盗 OPS${pa?f3(statCalc.battingOPS(s)):'.---'}`}const o=s.O||0;return`${S.year}年 防御率${o?statCalc.pitchingERA(s).toFixed(2):'-'} ${s.W||0}勝${s.L||0}敗${s.SV?' '+s.SV+'S':''}${s.HLD?' '+s.HLD+'H':''} ${s.SO||0}奪三振`};
const rs=p=>{const r=S.res;if(!r||!p)return null;const a=p.typ?r.pit:r.bat;if(!Array.isArray(a))return null;const x=a.find(x=>x.id!=null&&p.id!=null&&x.id===p.id)||a.find(x=>x.n===p.n);return x&&x.s||null};
function poor(p){const s=rs(p);if(!s)return false;if(!p.typ)return(s.PA||0)>=100&&statCalc.battingOPS(s)<.55;const o=s.O||0;return o>=90&&statCalc.pitchingERA(s)>5}
const abl=p=>p.typ?`球威${p.pwr} 制球${p.ctl} 変化${p.brk} 体力${p.sta}`:`ミ${p.con} 長${p.pow} 選${p.eye} 走${p.spd} 守${p.def}`;
const RN={SP:'先発',SU:'セットアッパー',RP:'中継ぎ',CL:'抑え'},BL={PH:'代打',DF:'守備',PR:'代走',BSP:'先発控え',BRP:'中継ぎ控え'},BRL=['PH','PH','DF','DF','DF','PR'];
