function vDraft(){const b=S.ph=='b',L=b?S.B:S.P;return`<h2>${b?'野手':'投手'}ドラフト ${L.length+1}/${b?9:12}巡目</h2><p class=s>5人から1人を選んで「決定」</p>${need(b,L)}${S.cand.map(card).join('')}<div class=c><b>指名済 ${L.length}人</b>${b?'':` <span class=s>先発候補${L.filter(p=>!p.rp).length}人 / 中継ぎ候補${L.filter(p=>p.rp).length}人</span>`}${L.map(p=>`<div class=s>${p.n}(${p.t}) / ${b?p.pos+(p.alt?'(副'+al(p).join('・')+')':''):(p.rp?'中継ぎ候補':'先発候補')}</div>`).join('')||'<div class=s>なし</div>'}</div><div class=bb><button class=g onclick="rr()" ${S.rr?'':'disabled'}>引き直し(残${S.rr})</button><button onclick="ok()" ${S.sel==null?'disabled':''}>決定</button></div>`}
