const al=b=>b.alt?b.alt.split('/'):[],fm=(b,p)=>p=='DH'?1:b.pos==p?1:al(b).includes(p)?(hk(b,'utl')?.97:.9):hk(b,'utl')?.8:.7,fl=(b,p)=>p=='DH'?'-':['△','○','◎'][fm(b,p)>.95?2:fm(b,p)>.8?1:0],sc=(b,p)=>(b.pos==p?100:al(b).includes(p)?60:0)+b.def*.5+b.bt*.5;
